mapper.select:
select distinct sub.prod_id as prodId from chb_prd_deal_sub sub
where 1=1 and sub.send_status != '01' and sub.mdate = #{batchDate,jdbcType = DATE}
and sub.prod_id in
#{accountid}

select IFNULL(deal.fprod_id,deal.prod_id) prodId, deal.org_code orgCode, deal.trade_type tradeType, IF(DEAL.TRADE_TYPE='04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE) payDate,
CASE WHEN #{openProdMdateConf,jdbcType=VARCHAR} = '02' AND DEAL.TRADE_TYPE IN ('04', '05', '14', '15') and OPEN1.PROD_ID is not null THEN IF(DEAL.TRADE_TYPE='04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE) WHEN #{openProdMdateConf,jdbcType=VARCHAR} = '02' AND DEAL.TRADE_TYPE IN ('02', '03', '17') THEN IFNULL(OPEN1.OPEN_END, IFNULL(OPEN1.OPEN_VDATE,DEAL.SETTDATE_DATE)) ELSE IFNULL(OPEN1.OPEN_VDATE,IF(DEAL.TRADE_TYPE='04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE)) END settdateDate,
/*CASE WHEN '02' = '02' AND DEAL.TRADE_TYPE IN ('04', '05', '14', '15') AND OPEN1.OPEN_END IS NOT NULL THEN IF(DEAL.TRADE_TYPE='04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE) ELSE IFNULL(OPEN1.OPEN_END, IF(DEAL.TRADE_TYPE='04',DEAL.INTEREST_DATE, DEAL.SETTDATE_DATE)) END AS settdateDate,*/
deal.ccy, sum(IFNULL(deal.int_amt,0)) intAmt, max(IFNULL(deal.unit_bonus_amount,0)) unitBonusAmount, sum(IFNULL(deal.trade_qty,0)) tradeQty, sum(IFNULL(deal.trade_prince,0)) tradePrince from chb_prd_deal deal /* add by dubaojun 2020-05-26 青岛银行信息披露与监管报送 start */ LEFT JOIN CHB_PRD_OPENSCH OPEN1 ON IFNULL(DEAL.FPROD_ID,DEAL.PROD_ID) = OPEN1.PROD_ID AND IF(DEAL.TRADE_TYPE='04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE) = OPEN1.OPEN_VDATE AND OPEN1.STATUS != 'D' AND OPEN1.PLAN_TYPE = IF(DEAL.TRADE_TYPE='03', '02', '01') /* add by dubaojun 2020-05-26 青岛银行信息披露与监管报送 end */ left join chb_prd_baseinfo info1 on DEAL.PROD_ID = info1.PROD_ID where deal.status != 'D'
AND (DEAL.TRADE_TYPE not in ('01','14','15') or (DEAL.TRADE_TYPE in ('14','15') and deal.SETTDATE_DATE != info1.vdate))
and (deal.BUY_PLACE not in('210200','330200','350200','370200','440300') or deal.BUY_PLACE is null)
IFNULL(deal.fprod_id,deal.prod_id) = #{prdDealSub.prodId,jdbcType = VARCHAR}
and IF(DEAL.TRADE_TYPE='04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE)
between #{prdDealSub.openEnd,jdbcType = DATE} and #{prdDealSub.openEnd1,jdbcType = DATE}
group by IFNULL(deal.fprod_id,deal.prod_id), deal.org_code, deal.trade_type, IF(DEAL.TRADE_TYPE='04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE), deal.ccy, OPEN1.OPEN_END, OPEN1.PROD_ID, OPEN1.OPEN_VDATE, DEAL.SETTDATE_DATE

SELECT IFNULL(FPROD_ID,PROD_ID) prodId, PROD_NAME prodName, ORG_CODE orgCode, FEE_ID feeId, FEE_NAME feeName, CCY ccy, SUM(IFNULL(AMT,0)) amt, PAY_DATE payDate FROM CHB_PRD_FEE_DEAL INFO WHERE INFO.STATUS !='D' AND INFO.FEE_TYPE = '01'
IFNULL(info.fprod_id,info.prod_id) = #{prdDealSub.prodId,jdbcType = VARCHAR}
and info.pay_date
= #{prdDealSub.openEnd,jdbcType = DATE}
group by IFNULL(FPROD_ID,PROD_ID), PROD_NAME, ORG_CODE, FEE_ID, FEE_NAME, CCY, PAY_DATE

select
yield.prod_value prodValue,yield.ccy,
yield.change_date changeDate
from chb_prd_periodyield yield
where yield.change_date = (select max(change_date)
from chb_prd_periodyield yield1
where yield1.prod_id = yield.prod_id

and yield1.status != 'D'

	and yield1.change_date < #{date,jdbcType = DATE}


	and yield1.change_date <=#{date,jdbcType = DATE}
)
AND yield.prod_id = #{prodId, jdbcType = VARCHAR}

AND 1 = 1 limit 1

SELECT
TDADD_INTAMT tdaddIntamt,
CCY ccy
FROM CHB_PRD_POSITION POS
WHERE POS.CDATE = #{date,jdbcType = DATE}
AND POS.PROD_ID = #{prodId, jdbcType = VARCHAR}
AND POS.CCY =  #{ccy, jdbcType = VARCHAR}

